@export var speed: float = 300.0
@export var dash_speed: float = 900.0
@export var dash_time: float = 0.15
@export var dash_cd: float = 0.6
var _dash_t: float = 0.0
var _cd_t: float = 0.0
var _dir_dash := Vector2.RIGHT

func _physics_process(delta: float) -> void:
	_cd_t = maxf(0.0, _cd_t - delta)
	var dir := Input.get_vector("move_left", "move_right", "move_up", "move_down")
	if Input.is_action_just_pressed("dash") and _cd_t == 0.0:
		_dash_t = dash_time
		_cd_t = dash_cd
		_dir_dash = dir if dir != Vector2.ZERO else velocity.normalized()
	if _dash_t > 0.0:
		_dash_t -= delta
		velocity = _dir_dash * dash_speed
	else:
		velocity = dir * speed
	move_and_slide()

extends CharacterBody2D

@export var speed: float = 300.0
@export var jump_velocity: float = -450.0
@export var wall_slide_speed: float = 80.0
@export var wall_push: float = 300.0

func _physics_process(delta: float) -> void:
	var dir := Input.get_axis("move_left", "move_right")
	var na_parede := is_on_wall_only()
	if not is_on_floor():
		velocity += get_gravity() * delta
		if na_parede and velocity.y > 0.0:
			velocity.y = minf(velocity.y, wall_slide_speed)
	if Input.is_action_just_pressed("jump"):
		if is_on_floor():
			velocity.y = jump_velocity
		elif na_parede:
			velocity.y = jump_velocity
			velocity.x = -get_wall_normal().x * wall_push
	velocity.x = move_toward(velocity.x, dir * speed, speed)
	move_and_slide()

extends CharacterBody2D

