signal vida_alterada(atual: float, maximo: float)

@export var vida_maxima: float = 100.0
@export var regen_por_seg: float = 5.0
@export var atraso_apos_dano: float = 3.0
var vida: float
var _sem_dano: float = 0.0

func _ready() -> void:
	vida = vida_maxima

func _process(delta: float) -> void:
	_sem_dano += delta
	if _sem_dano >= atraso_apos_dano and vida < vida_maxima:
		vida = minf(vida_maxima, vida + regen_por_seg * delta)
		vida_alterada.emit(vida, vida_maxima)

func receber_dano(qtd: float) -> void:
	vida = maxf(0.0, vida - qtd)
	_sem_dano = 0.0
	vida_alterada.emit(vida, vida_maxima)

