@export var dano_por_seg: float = 8.0
var _restante: float = 0.0
var _acumulado: float = 0.0

func aplicar(duracao: float) -> void:
	_restante = maxf(_restante, duracao)

func _process(delta: float) -> void:
	if _restante <= 0.0:
		return
	_restante -= delta
	_acumulado += dano_por_seg * delta
	while _acumulado >= 1.0:
		_acumulado -= 1.0
		var alvo := get_parent()
		if alvo and alvo.has_method("receber_dano"):
			alvo.receber_dano(1)

extends Node

