@export var sensibilidade: float = 0.005
@onready var _arm: SpringArm3D = $SpringArm3D

func _ready() -> void:
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED

func _unhandled_input(evento: InputEvent) -> void:
	if evento is InputEventMouseMotion:
		rotate_y(-evento.relative.x * sensibilidade)
		if _arm:
			_arm.rotate_x(-evento.relative.y * sensibilidade)
			_arm.rotation.x = clampf(_arm.rotation.x, -1.2, 0.4)

extends Node3D

@onready var _ray: RayCast3D = $RayCast3D

func _unhandled_input(evento: InputEvent) -> void:
	if evento.is_action_pressed("interact") and _ray and _ray.is_colliding():
